<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'auth' }); const route = useRoute(); const spotId = String(route.params.spotId); const { data, refresh } = await useFetch(`/api/spot-editor/spots/${spotId}/revision`)
const form = reactive({ name: '', description: '', address: '', phone: '', website: '', hoursText: '', holidayText: '' }); const photoAssetIds = ref<string[]>([]); const message = ref('')
watchEffect(() => { const source: any = data.value?.revision?.payload ?? data.value?.spot; if (source) for (const key of Object.keys(form)) (form as any)[key] = source[key] ?? ''; photoAssetIds.value = data.value?.revision?.photos?.map((photo: any) => photo.assetId) ?? data.value?.spot?.photos?.map((photo: any) => photo.assetId) ?? [] })
async function save() { await $fetch(`/api/spot-editor/spots/${spotId}/revision`, { method: 'PUT', body: { ...form, description: form.description || null, address: form.address || null, phone: form.phone || null, website: form.website || null, hoursText: form.hoursText || null, holidayText: form.holidayText || null, fieldValues: data.value?.spot.fieldValues.map((item: any) => ({ fieldDefinitionId: item.fieldDefinitionId, valueJson: item.valueJson })) ?? [], photoAssetIds: photoAssetIds.value } }); message.value = '承認待ちとして保存しました。'; await refresh() }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const body = new FormData(); body.append('file', file); const result = await $fetch(`/api/spot-editor/spots/${spotId}/photos`, { method: 'POST', body }); photoAssetIds.value.push(result.image.assetId) }
</script>
<template><section class="max-w-2xl"><NuxtLink to="/admin/spot-editor" class="text-sm underline">← 担当Spotへ</NuxtLink><h1 class="mt-5 text-2xl font-bold">Spot情報の編集</h1><p v-if="data?.blockedByPreviousAssignee" class="mt-4 rounded bg-amber-50 p-4">前の担当者の承認待ちRevisionがあるため、レビュー完了まで新しい編集は保存できません。</p><p v-if="message" class="mt-4 rounded bg-green-50 p-4">{{ message }}</p><form class="mt-6 space-y-4 rounded-xl bg-white p-6" @submit.prevent="save"><label v-for="key in Object.keys(form)" :key="key" class="block text-sm font-semibold">{{ key }}<textarea v-if="['description','hoursText','holidayText'].includes(key)" v-model="(form as any)[key]" class="mt-1 w-full rounded border px-3 py-2"/><input v-else v-model="(form as any)[key]" :type="key === 'website' ? 'url' : 'text'" :required="key === 'name'" class="mt-1 w-full rounded border px-3 py-2"></label><div><label class="text-sm font-semibold">新しい写真<input type="file" accept="image/png,image/jpeg" class="mt-2 block" @change="upload"></label><p class="mt-2 text-xs">選択中: {{ photoAssetIds.length }}件（Tenant Media Libraryの閲覧はできません）</p></div><button :disabled="data?.blockedByPreviousAssignee" class="rounded bg-stone-900 px-4 py-3 font-semibold text-white disabled:opacity-40">承認待ちとして保存</button></form></section></template>
